package status

import (
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/status"
	"github.com/anthnel/devdesk/internal/ui/datatable"
)

func TestZZSweep(t *testing.T) {
	exp := time.Date(2026, 12, 1, 10, 30, 0, 0, time.UTC)
	d := 42
	items := []status.ComponentStatus{
		{Name: "wildcard-prod", Type: status.TypeSSL, Target: "api.prod.example.com", Status: status.StatusOK, SSLDaysLeft: &d, SSLExpires: &exp, SSLIssuer: "Let's Encrypt"},
	}
	for _, w := range []int{60, 80, 100, 120, 160, 200} {
		tb := datatable.New(sslColumns())
		tb.SetItems(items)
		tb.Resize(w, 10)
		got := tb.RenderedWidth()
		names := ""
		for _, c := range tb.Table().Columns() {
			names += " " + c.Title + "=" + itoa(c.Width)
		}
		t.Logf("w=%3d rendered=%3d want=%3d |%s", w, got, w-2, names)
		if got != w-2 {
			t.Errorf("w=%d rendered=%d want %d", w, got, w-2)
		}
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	s := ""
	for n > 0 {
		s = string(rune('0'+n%10)) + s
		n /= 10
	}
	return s
}
GOEOF
